from pathlib import Path
import re,json
root=Path(__file__).resolve().parents[1]
notes={'2006_1': ['惯性系应定义为无外力质点保持静止或匀速直线运动的参考系；旋转系相对惯性系转动。原解适用于地球近似恒定角速度、原点平动加速度另处理的情况；一般变角速度旋转系还需欧拉惯性力，不能只列科氏和离心两项便称完全一般。', '正压与斜压定义正确；等压面温度均匀结论对定组成理想干气体成立，湿空气应使用虚温。地转风切变结论依赖静力及地转平衡，不是所有实际风的性质。', '正压不稳定取能于基本流水平切变动能，斜压不稳定取能于基本态有效位能。Rayleigh–Kuo积分虚部、能量转换负号核对一致，但变号仅为所用通道模型的必要条件；两种机制可并存，不能把有切变直接当作已不稳定。', '取旋度消去压力梯度须限定其为保守梯度，如等压面位势梯度；一般高度坐标的密度变化会留下斜压项。涡度式突出旋转演变，但单独不能恢复散度、质量场或所有风场信息。', 'Kelvin波的v为零、东传与高斯束缚正确；混合波v非零且有频散，西向相速可配东向群速。补充标准最低阶模态的经向风关于赤道对称、纬向风及高度扰动反对称，与Kelvin的对称高度/纬向风不同。', '原方程待核：常f动量式的旋度与另加βv的涡度式不相容。替代局地模型的三次式代数正确，但k、f0非零及截断层级须注明，不能作为原四式的精确一般解。', '在已声明的替代局地近似下，区分慢罗斯贝波与快惯性重力波，后者有两个传播分支。慢波内禀纬向相速向西、偏涡旋性；快波重力/旋转回复且辐散明显。上一题的原方程疑点仍未消除。', '在北半球圆流、径向向外、切向逆时针为正的约定下，径向平衡及气旋次地转、正常反气旋超地转均正确。反气旋判别式约束的是同曲率地转风；须区分正常支和另一数学根，不可将向心加速度另加成真实力。', '受力比较应限同纬度、同水平压力梯度与规定曲率。图中低压压力梯度力向内、科氏力向外；高压相反且合力仍向内。原图已定位并恢复；地转风比较是忽略曲率项的参照，而非实际圆周运动的另一个平衡。'], '2010': ['非地转风定义和叉积解符号正确；地转风严格无散仅在常f等压面局地模型成立，β平面有相应修正。非地转风影响质量调整与垂直运动，不能说任何情况下全部散度都只由它贡献。', '题目问三种尺度量，应先列长度L、时间T、速度U及物理含义，必要时另列垂直尺度H。Ro、Fr、Ma是由尺度量组成的无量纲数，不能拿它们替代三种有量纲尺度的回答。', '惯性回复系数f(f-Uy)及干对称不稳定的fq判据适用于所列平行基本流和沿锋不变扰动。对称不稳定需排除纯静力、惯性不稳定，湿情况还需饱和及恰当湿位涡，不能只凭负位涡就断言已出现斜向对流。', '模态波速、变形半径和热成风约束的说明正确。局地平衡成分由初始位涡、边界和质量共同约束；波能可离开局地的条件需保留，封闭无耗散域不保证全部振荡消失。', '应力取地面对空气时，输送和抽吸公式符号一致。spin down是边界摩擦通过次级环流将影响传入内部、使旋转减弱；Ri、Re不是本题核心定义，不能代替这一机制。', '浅水位涡商法则推导正确。题干d/dt须解释为水平物质导数，h为正的层厚，保持无摩擦无源汇。无关且混用常f和β的第五步已从本题副本删除。', '原题待核：H0(x)与非零y向梯度不相容，须明确改成H(y)。一致β平面基本态应满足$g\\frac{\\partial H}{\\partial y}=-f(y)U$；常数U的线性涡度式为$(\\frac{\\partial}{\\partial t}+U\\frac{\\partial}{\\partial x})\\zeta\\prime+\\beta v\\prime+f(y)D\\prime=0$。只有进一步局地近似才将最后f(y)换f0；不能先把两动量式精确取常f，再直接推出β项。', '原题待核且仅条件解：已核对所列局地冻结系数模型的消元符号，层厚梯度项为正gf0kHy；用gHy=-f0U后得原解慢根。该模型额外省略散度式β修正，非原全域变系数系统的精确解；快根仅零阶，低频近似须小于惯性重力频率，不能对任意U和k使用。', '应将正压不稳定的切变动能取能与CISK的对流加热—摩擦辐合反馈并列说明。Rayleigh–Kuo必要条件不能替代物理机制；CISK也不是单气块条件不稳定或台风发展的充分条件。', '地转风表达式、等高线方向和半球左右规则正确；须附远离赤道、弱摩擦和小水平加速度条件。风速还依f，不能跨纬度只比较等高线疏密。', '锋区为不同气团间具有较强温度/密度梯度的三维过渡带，锋面和锋线分别是理想界面与地面交线。气压一般连续；随高度向冷侧倾斜不是锋面本身在上升。', '先答强冷空气引起显著大范围降温、大风及可能雨雪冻害，业务判定需注明时长、降温与最低温度标准。原资料未列具体阈值，本次不据泛化过程宣称已核实全部业务等级。', '线状组织对流系统定义正确，冷池及触发抬升可帮助新生对流。冰雹、层状降水和每站骤降温不是必备条件；一次飑不必构成飑线。', '热带东风背景中的波状槽脊、典型西移和可能提供初始涡旋的表述合理。波相位传播不等同气块轨迹，不是每个东风波都会发展成热带气旋。', '需同时完成天气和500 hPa两问：春至初夏降水频繁、可有锋面/暖区强降水；中层南支槽或短波槽与副高边缘配置利于水汽和抬升。低空急流是补充垂直配置，不能当500 hPa系统；训练效应指单体反复经过相近区域。', '发生条件与三场结构均覆盖。气压中心低、暖心相对周围同高度空气、低层入流眼墙上升高层外流；眼墙贯穿较深层并非只在中层，最大风常在低层眼墙附近。26.5℃、弱切变等为经验有利条件而非独立充分条件。', '应将动力绕流与下游定常波、热力高架热源与上层南亚高压联系，再说明通过季风/加热分布影响副高位置强度。南亚高压也受南亚季风凝结加热影响，不能全部归因高原感热；原解“四种以上”非本题要求。']}
review={}
for year,items in notes.items():
 source=root.parent/('动力气象课后习题/试题解答/往年试题解析/'+year+'.md')
 ids=re.findall(r'^## 题目 (.+)$',source.read_text(encoding='utf-8'),re.M)
 assert len(ids)==len(items),(year,len(ids),len(items))
 review.update(zip(ids,items))
(root/'scripts/review_2006_1_2010.json').write_text(json.dumps(review,ensure_ascii=False,indent=2),encoding='utf-8')
for p in (root/'每日内容').glob('D*.md'):
 s=p.read_text(encoding='utf-8')
 for q,note in review.items():
  pattern=r'^(### '+re.escape(q)+r'[^\n]*)\n(?:\n\*\*本次复核提示（2026-11-01）：\*\* [^\n]*\n)?'
  s=re.sub(pattern,lambda m:m[1]+'\n\n**本次复核提示（2026-11-01）：** '+note+'\n',s,flags=re.M)
 s=s.replace('白天对流层可较深','白天对流边界层可较深')
 p.write_text(s,encoding='utf-8')
p=root/'逐题复核记录.md';s=p.read_text(encoding='utf-8').replace('2005_1及2006年共222条记录','2005_1、2006、2006_1及2010年共248条记录').replace('其中11题','其中15题').replace('其余314题','其余288题')
lines=[]
for line in s.splitlines():
 m=re.match(r'\| \[([^\]]+)\]',line)
 if m and m[1] in review:
  line=line.replace('结构核对完成；学科内容待复核','内容复核；原卷/教材口径待核' if m[1] in ['2006_1-二-1','2006_1-二-2','2010-二-2','2010-二-3'] else '内容复核（2026-11-01）').replace('仅核对题号、题干/解答段落，未据此宣称答案正确。',review[m[1]].replace('|',r'\|'))
 lines.append(line)
p.write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Reviewed',len(review),'questions')
